-- AUTO-GENERATED LAUNCHER FOR LOCAL DEVELOPMENT.
--
-- This file is automatically generated by `npm run setup-resolve` from the
-- template in src-tauri/resources/AutoSubs (Dev).lua. It points Resolve at your
-- local AutoSubs source tree and starts the core server in development mode.
--
-- NO EDITING NEEDED: just run `npm run setup-resolve` from AutoSubs-App/.
-- The copy of this file that lives in your DaVinci Resolve scripts folder is
-- generated from the template in the repo (src-tauri/resources/AutoSubs (Dev).lua)
-- by running, from the AutoSubs-App directory:
--
--     npm run setup-resolve
--
-- That command bakes the absolute path to your local checkout into the line
-- below, so this launcher is fully self-contained: it points Resolve directly
-- at the AutoSubs source tree and starts the core server in development mode.
-- It does NOT require AutoSubs to be installed normally first, and it never
-- loads AutoSubs.lua. Edits to the Lua modules are picked up the next time you
-- run this script from Resolve (no rebuild needed).

-- `npm run setup-resolve` replaces the placeholder below with the absolute path
-- to the repo's `src-tauri/resources` folder.
local resources_folder = [[__AUTOSUBS_RESOURCES_FOLDER__]]

if resources_folder == "__AUTOSUBS_RESOURCES_FOLDER__" then
    error(
        "'AutoSubs (Dev).lua' has not been generated yet. Run `npm run setup-resolve` " ..
        "from the AutoSubs-App directory to create a configured copy in your " ..
        "DaVinci Resolve scripts folder."
    )
end

-- Load the bootstrap (the sandboxed scripting state has no require/package,
-- and on Resolve 21.2 no loadfile); it sets up module loading and starts the
-- core server.
-- mode = "manual": running this script restarts the bridge against your repo
-- checkout (it stops any running bridge first, including one a 3.10.0 startup
-- scriptlib left behind).
local bootstrap_path = resources_folder .. "/modules/bootstrap.lua"
-- Resolve 21.2 also removed loadfile from this state, but fusion:OpenFile
-- (mode 1 = read) still reads files, so the bootstrap is read line by line
-- and compiled with loadstring. Older Resolve versions keep loadfile.
local function load_lua_file(path)
    local native = rawget(_G, "loadfile")
    if native then
        return native(path)
    end
    local fu = rawget(_G, "fusion") or rawget(_G, "fu")
    local ok, h = pcall(function() return fu:OpenFile(path, 1) end)
    if not ok or not h then
        return nil, "could not open " .. path
    end
    local parts = {}
    while true do
        local line = h:ReadLine()
        if line == nil or line == "" then
            break
        end
        parts[#parts + 1] = line
    end
    h:Close()
    return loadstring(table.concat(parts), "@" .. path)
end
local boot = assert(load_lua_file(bootstrap_path))()

-- No executable path is needed in dev mode: the core server never launches the
-- desktop app while dev mode is enabled.
return boot(resources_folder, "", true, { mode = "manual" })

